export const getRegistrarPagoUrl = (facturaId: string) => {
  return `/api/v1/facturas/${facturaId}/pagos`;
};

/**
 * Monto > 0 y ≤ saldo (si no, 400 VALIDACION o 422 PAGO_EXCEDE_SALDO). La misma referencia y medio en la misma factura
 * con otra clave responde 409 PAGO_DUPLICADO con la extensión `pagoId` del pago existente.
 * @summary Administración registra un pago (spec 008); baja el saldo, abona la línea y publica PagoRegistrado.
 */
export const registrarPago = async (
  facturaId: string,
  pagoNuevo: PagoNuevo,
  options?: Parameters<typeof pedirFinanzas>[1],
): Promise<Factura> => {
  const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]));
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return pedirFinanzas<Factura>(getRegistrarPagoUrl(facturaId), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(pagoNuevo),
  });
};

